source('R/stile.R');d<-read.csv('dati/progetti/rock.csv');out<-'risultati/P01';dir.create(out,recursive=TRUE,showWarnings=FALSE)
verifica('48 sezioni e 12 gruppi ricostruiti',nrow(d)==48&&length(unique(d$core_id))==12&&all(table(d$core_id)==4))
verifica('permeabilita comune dentro carota',all(tapply(d$permeability_md,d$core_id,function(x)length(unique(x)))==1))
verifica('dominio area e permeabilita',all(d$area_pixels>=0&d$area_pixels<=256^2)&all(d$permeability_md>0))
verifica('valori originali R',isTRUE(all.equal(d$area_pixels,as.numeric(datasets::rock$area)))&&isTRUE(all.equal(d$permeability_md,as.numeric(datasets::rock$perm))))
d$pore_area_pct<-100*d$area_pixels/256^2;c<-aggregate(cbind(pore_area_pct,permeability_md)~core_id,d,mean);c<-c[order(c$core_id),];c$log10_k<-log10(c$permeability_md)
salva('P01','F01',ggplot(d,aes(pore_area_pct,permeability_md))+geom_point(colour=geo[1],size=2)+scale_y_log10(breaks=c(10,100,1000),labels=c('10','100','1000'))+scale_x_continuous(breaks=c(0,10,20))+labs(x='Frazione areale (%)',y='Permeabilità (mD)'))
c$lx<-c$pore_area_pct+c(0,0,0,0,0,0,-.4,-.35,.35,0,0,-.4);c$ly<-c$log10_k+c(.17,.17,.17,.17,.17,.17,.12,.25,.12,.17,.25,-.15)
salva('P01','F02',ggplot(c,aes(pore_area_pct,log10_k))+geom_point(colour=geo[1],size=2.8)+geom_segment(aes(xend=lx,yend=ly),colour=geo[6],linewidth=.25)+geom_text(aes(x=lx,y=ly,label=core_id),size=5.2)+scale_x_continuous(breaks=c(5,10,15))+scale_y_continuous(breaks=1:3)+labs(x='Frazione areale media (%)',y='log10(K / 1 mD)'))
fit<-lm(log10_k~pore_area_pct,c);beta<-unname(coef(fit)[2]);ct<-unname(confint(fit)[2,]);g<-data.frame(pore_area_pct=seq(min(c$pore_area_pct),max(c$pore_area_pct),length.out=150));pr<-predict(fit,g,interval='confidence');gg<-cbind(g,pr)
salva('P01','F03',ggplot(gg,aes(pore_area_pct,fit))+geom_ribbon(aes(ymin=lwr,ymax=upr),fill=geo[2],alpha=.15)+geom_line(colour=geo[2],linewidth=.8)+geom_point(data=c,aes(pore_area_pct,log10_k),inherit.aes=FALSE,colour=geo[1],size=2.4)+scale_x_continuous(breaks=c(5,10,15))+scale_y_continuous(breaks=0:4)+labs(x='Frazione areale media (%)',y='log10(K / 1 mD)'))
ix<-as.matrix(read.csv('dati/progetti/piani_ricampionamento/rock_cores.csv'));boot<-apply(ix,1,function(i)unname(coef(lm(log10_k~pore_area_pct,c[i,]))[2]));cb<-quantile(boot,c(.025,.975),type=7)
verifica('piano bootstrap e stime finite',nrow(ix)==4000&&ncol(ix)==12&&all(ix>=1&ix<=12)&&all(is.finite(boot)))
salva('P01','F04',ggplot(data.frame(beta=boot),aes(beta))+geom_histogram(bins=35,fill=geo[1],colour=paper,linewidth=.2)+geom_vline(xintercept=0,linetype=2,colour=geo[3])+geom_vline(xintercept=cb,linetype=3,colour=geo[2])+scale_x_continuous(breaks=c(-.4,-.2,0,.2),labels=fmt)+labs(x='Pendenza per punto %',y='Ricampionamenti'))
res<-data.frame(stima=fitted(fit),residuo=resid(fit),carota=c$core_id)
salva('P01','F05',ggplot(res,aes(stima,residuo))+geom_hline(yintercept=0,colour=geo[6],linetype=2)+geom_point(colour=geo[1],size=2.4)+scale_x_continuous(breaks=c(1.8,2.2,2.6),labels=fmt)+scale_y_continuous(labels=fmt)+labs(x='Stima in scala log10',y='Residuo'))
leave<-sapply(seq_len(nrow(c)),function(j)unname(coef(lm(log10_k~pore_area_pct,c[-j,]))[2]));loo<-data.frame(carota=c$core_id,beta=leave)
salva('P01','F06',ggplot(loo,aes(carota,beta))+geom_hline(yintercept=beta,colour=geo[2],linetype=2)+geom_hline(yintercept=0,colour=geo[6])+geom_line(colour=geo[1],linewidth=.7)+geom_point(colour=geo[1],size=2.2)+scale_x_continuous(breaks=c(1,4,8,12))+scale_y_continuous(labels=fmt)+labs(x='Carota esclusa',y='Pendenza stimata'))
verifica('residui OLS ortogonali',max(abs(crossprod(model.matrix(fit),resid(fit))))<1e-10)
verifica('coefficiente da covarianza',abs(beta-cov(c$pore_area_pct,c$log10_k)/var(c$pore_area_pct))<1e-12)
shape<-d$perimeter_pixels/sqrt(d$area_pixels);verifica('shape incompatibile con formula documentata',max(abs(shape-d$shape_original))>1)
write.csv(c,file.path(out,'carote.csv'),row.names=FALSE);write.csv(data.frame(beta=boot),file.path(out,'bootstrap.csv'),row.names=FALSE);write.csv(loo,file.path(out,'influenza.csv'),row.names=FALSE)
jsonlite::write_json(list(n_sezioni=48,n_carote=12,beta=beta,IC_t=ct,IC_boot=cb,p=summary(fit)$coefficients[2,4],R2=summary(fit)$r.squared,fattore=10^beta,loo=range(leave),df=df.residual(fit),se=summary(fit)$coefficients[2,2]),file.path(out,'valori.json'),pretty=TRUE,auto_unbox=TRUE,digits=12)
interv<-data.frame(metodo=factor(c('t, 10 gdl','Bootstrap'),levels=c('Bootstrap','t, 10 gdl')),stima=beta,basso=c(ct[1],cb[1]),alto=c(ct[2],cb[2]))
salva('P01','F07',ggplot(interv,aes(stima,metodo))+geom_vline(xintercept=0,colour=geo[6],linetype=2)+geom_errorbarh(aes(xmin=basso,xmax=alto),height=.15,colour=geo[2],linewidth=.9)+geom_point(colour=geo[1],size=3)+scale_x_continuous(breaks=c(-.2,-.1,0),labels=fmt)+labs(x='Pendenza per punto %',y=NULL))
